// Zwei Dinge bewacht dieser Workflow, seit die KI selbst mergen darf:
//
//   1. status:freigegeben — Gate G2, das setzt nur ein Mensch
//   2. gemergte PRs auf geschuetzte Pfade — der Selbstumbau
//
// Punkt 2 ist bewusst doppelt: der Check 'pfade' in pr-pruefung.yml sollte
// das schon verhindern. Genau deshalb steht er hier noch einmal. Wenn hier
// je Alarm ausgeloest wird, ist nicht der PR das Problem, sondern dass der
// Check umgangen werden konnte.

const b = $input.first().json.body || $input.first().json;

// Muss zu scripts/menschen.txt passen.
const MENSCHEN = ['firat-keskin'];

const akteur = b.sender?.login || 'unbekannt';
const akteurTyp = b.sender?.type || 'unbekannt';
const istMensch = akteurTyp === 'User' && MENSCHEN.includes(akteur);
const repo = b.repository?.full_name || '';

const leer = {
  verstoss: false, art: 'ignoriert', akteur, akteurTyp, repo,
  nummer: null, titel: '', url: '', text: ''
};

// --- Fall 1: jemand hat status:freigegeben gesetzt ---
if (b.action === 'labeled' && b.label?.name === 'status:freigegeben') {
  return [{ json: {
    ...leer,
    art: 'label',
    verstoss: !istMensch,
    nummer: b.issue?.number,
    titel: b.issue?.title || '',
    url: b.issue?.html_url || '',
    text: 'status:freigegeben wurde nicht von einem Menschen gesetzt. Label wird zurueckgenommen.'
  }}];
}

// --- Fall 2: ein PR wurde gemergt ---
// Der Webhook liefert keine Dateiliste mit. Der naechste Node holt sie ueber
// die API nach; hier wird nur entschieden, ob es sich lohnt hinzuschauen.
if (b.action === 'closed' && b.pull_request?.merged === true) {
  return [{ json: {
    ...leer,
    art: 'merge',
    verstoss: false,
    pruefen: true,
    nummer: b.pull_request.number,
    titel: b.pull_request.title || '',
    url: b.pull_request.html_url || '',
    merger: b.pull_request.merged_by?.login || akteur
  }}];
}

return [{ json: leer }];

// Nachtraeglich pruefen, ob ein gemergter PR geschuetzte Pfade angefasst hat.
// Muss zu .github/geschuetzte-pfade.txt passen.
const GESCHUETZT = [
  /^CLAUDE\.md$/,
  /^\.claude\//,
  /^\.github\/workflows\//,
  /^\.github\/geschuetzte-pfade\.txt$/,
  /^scripts\/menschen\.txt$/,
  /^docs\/(plan|kunde)\.md$/,
  /^tests?\//,
  /(^|\/)(package(-lock)?\.json|pyproject\.toml|requirements\.txt|Dockerfile)$/
];

const kopf = $('Ereignis einordnen').first().json;
const dateien = $input.all().map(i => i.json.filename).filter(Boolean);
const betroffen = dateien.filter(d => GESCHUETZT.some(r => r.test(d)));

return [{ json: {
  ...kopf,
  dateien: dateien.length,
  betroffen,
  verstoss: betroffen.length > 0,
  text: betroffen.length
    ? 'Ein gemergter PR hat geschuetzte Pfade veraendert. Der Check "pfade" haette das anhalten muessen — pruefe, ob er als Required Status Check auf main eingetragen ist.'
    : ''
}}];
